        const e = &m.eng;
        const c = e.c;
        const ch = &m.ch;
        const rs = &m.rs;
        if (hi <= lo or hi > c.layers) return error.BadSlice;
        if (lo == 0) {
            m.dropChunk();
            try m.openChunk(seq, args);
        } else if (!rs.live or rs.next != lo or seq.len != rs.args.start + rs.args.n) return error.BadSlice;
        const start = rs.args.start;
        const n = rs.args.n;
        const replay = rs.args.replay;
        const pt = m.ptimer;
        const taps = m.dr != null;
